const text = ($input.first().json.content || []).map(b => b.text || '').join('').trim();
let ratings = [];
try {
  const a = text.indexOf('['); const b = text.lastIndexOf(']');
  if (a >= 0 && b > a) ratings = JSON.parse(text.slice(a, b + 1));
} catch { ratings = []; }
const SUPA='https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1';
const hdr={ apikey: $credentials.supabaseApi.apiKey, Authorization: `Bearer ${$credentials.supabaseApi.apiKey}`, Prefer: 'return=minimal' };
for (const r of ratings) {
  if (!r?.id) continue;
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPA}/tasks?id=eq.${r.id}`,
    headers: { ...hdr, 'Content-Type': 'application/json' },
    body: JSON.stringify({ lever_score: r.lever_score, est_hours_to_revenue: r.est_hours_to_revenue, lever_rated_at: new Date().toISOString() }),
    json: true,
  });
}
return [{ json: { rated: ratings.length } }];
